import sys, json
sys.path.insert(0,'data_sources')
from dotenv import load_dotenv; load_dotenv('data_sources/config/.env')
from modules.dataforseo import DataForSEO
dfs = DataForSEO()
def vol(kws, lang):
    data=[{"keywords":kws,"location_code":2756,"language_code":lang}]
    r = dfs._post("/v3/keywords_data/google_ads/search_volume/live", data)
    t = dfs._first_task(r); res = (t or {}).get('result') or []
    return {x['keyword']: (x.get('search_volume'), x.get('competition'), x.get('cpc')) for x in res}
